import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue of capacity cap accepts.

    Creates a bounded queue holding at most cap integers and tries to put
    each element of xs in order without blocking. Stops at the first put
    that fails because the queue is full, and returns the number of puts
    accepted before that point. A capacity of zero or less accepts nothing.
    """
    if cap <= 0:
        # queue.Queue treats maxsize <= 0 as unbounded, so handle it here.
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_cap_smaller_than_input() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_cap_equal_to_input() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-3, [1, 2]) == 0


def test_capacity_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_duplicates_are_all_counted() -> None:
    assert accepted(4, [5, 5, 5, 5, 5]) == 4


def test_does_not_block_when_full() -> None:
    # Would hang forever if the implementation used a blocking put.
    assert accepted(1, [1, 2, 3, 4, 5]) == 1


@pytest.mark.parametrize(
    ("cap", "n", "expected"),
    [(0, 5, 0), (1, 5, 1), (4, 5, 4), (5, 5, 5), (6, 5, 5)],
)
def test_accepted_is_min_of_cap_and_len(cap: int, n: int, expected: int) -> None:
    assert accepted(cap, list(range(n))) == expected


def test_queue_module_full_exception_exists() -> None:
    # Sanity check on the exception the implementation is expected to handle.
    q: queue.Queue[int] = queue.Queue(maxsize=1)
    q.put_nowait(1)
    with pytest.raises(queue.Full):
        q.put_nowait(2)
